(() => {
  'use strict';
  const camera='<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 10 5-3v10l-5-3z"/>';
  const svg=(paths=camera)=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">'+paths+'</svg>';
  function mount(){
    const detail=document.getElementById('detailDesignWorkspace');if(!detail)return false;
    if(document.getElementById('videoDesignWorkspace'))return true;
    const pair=document.createElement('section');pair.id='videoDesignWorkspace';pair.className='design-workspace video-design-workspace';pair.setAttribute('aria-label','视频设计与视频设置');
    pair.innerHTML=`<details id="videoDesignModule" open><summary class="workspace-section-header"><span class="workspace-header-icon">${svg()}</span><h2>视频设计</h2><span class="workspace-section-toggle">收起 ↑</span></summary>
      <div class="video-design-body"><div class="video-preview-column"><div class="video-preview-stage" id="videoPreviewStage"><video id="videoPlayer" controls playsinline preload="metadata" hidden></video><img id="videoSourcePreview" alt="视频首帧素材预览" hidden><div class="video-empty" id="videoEmpty">${svg()}<h3>让商品图片，成为动态作品</h3><p>上传一张商品图，或从已有作品中挑选，<br>用自然运镜展示花型、质感与工艺。</p><button type="button" id="videoEmptyUpload">选择商品图片</button></div><span id="videoPreviewBadge" hidden>首帧素材预览</span></div><div class="video-preview-footer"><span id="videoPreviewCaption">商品展示 · 连续镜头</span><a id="videoDownload" hidden download>↓ 下载视频</a></div></div>
      <div class="video-browser"><div class="video-browser-toolbar"><strong id="videoWorksCount">视频作品 · 0</strong><button type="button" id="videoRefresh">刷新记录</button></div><div id="videoJobList" class="video-job-list"></div><div class="video-workflow"><span>创作流程</span><h3>从静态到动态，保留商品本色</h3><p><b>01</b> 选择清晰的商品照片</p><p><b>02</b> 确认镜头与视频规格</p><p><b>03</b> 生成、预览并下载作品</p><small>视频独立保存，随时回到这里查看。</small></div></div></div></details>
      <aside id="videoSettingsPanel" class="detail-settings-rail video-settings-rail" aria-labelledby="videoSettingsTitle"><header class="settings-rail-header"><span class="settings-rail-icon">${svg()}</span><h2 id="videoSettingsTitle">视频设置</h2><button type="button" id="collapseVideoSettings" aria-expanded="true">收起 →</button></header><div class="detail-settings-body video-settings-body">
      <section class="detail-settings-section"><h3><b>01</b> 商品素材</h3><input type="file" id="videoSourceFile" accept="image/png,image/jpeg,image/webp" hidden><button type="button" id="videoUpload" class="video-upload">${svg('<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>')}<strong>上传商品图片</strong><small>点击或拖入 · PNG / JPG / WebP</small></button><div class="video-source-row" id="videoSourceRow" hidden><img id="videoSourceThumb" alt="已选视频素材"><div><strong id="videoSourceName"></strong><small>首帧图片</small></div><button type="button" id="videoClearSource" aria-label="移除视频素材">×</button></div><div class="video-source-actions"><button type="button" id="videoUseCurrent">使用当前图片</button><button type="button" id="videoPickHistory">从作品中挑选</button></div></section>
      <section class="detail-settings-section"><h3><b>02</b> 镜头与动态</h3><div class="video-motion-grid" role="group" aria-label="视频镜头"><button type="button" data-motion="push" aria-pressed="true"><strong>缓慢推进</strong><small>整体到局部</small></button><button type="button" data-motion="slide" aria-pressed="false"><strong>横向运镜</strong><small>自然空间视差</small></button><button type="button" data-motion="detail" aria-pressed="false"><strong>细节展示</strong><small>花型与缝线</small></button><button type="button" data-motion="still" aria-pressed="false"><strong>静谧氛围</strong><small>克制光影变化</small></button></div><label class="video-field" for="videoPrompt">补充要求 <span>选填</span></label><textarea id="videoPrompt" maxlength="600" placeholder="例如：镜头缓慢靠近床品，保留原有花色，不添加人物"></textarea></section>
      <section class="detail-settings-section"><h3><b>03</b> 视频规格</h3><div class="video-spec-grid"><label for="videoDuration">视频时长<select id="videoDuration"><option value="5">5 秒</option><option value="10">10 秒</option></select></label><label for="videoRatio">画面比例<select id="videoRatio"><option value="source">跟随原图</option><option value="9:16">9 : 16</option><option value="16:9">16 : 9</option><option value="1:1">1 : 1</option></select></label><label for="videoQuality">生成模式<select id="videoQuality"><option value="quality">画质优先</option><option value="speed">速度优先</option></select></label><label class="video-audio" for="videoAudio"><input type="checkbox" id="videoAudio">生成音效</label></div><p class="video-spec-note">跟随原图保留图片比例；固定比例由模型适配。</p></section>
      <section class="video-generate-card"><div class="video-generate-heading">${svg()}<div><small>AI 商品视频</small><h3>准备生成</h3></div><span id="videoPlan">1 条 · 5 秒</span></div><div class="video-service-line"><span id="videoServiceStatus">正在读取视频服务</span><button type="button" id="videoConfigure">配置服务</button></div><button type="button" id="videoGenerate">${svg()} 生成视频</button><button type="button" id="videoCancel" hidden>停止跟踪</button><progress id="videoProgress" max="100" hidden aria-label="视频生成进度"></progress><p id="videoStatus" role="status" aria-live="polite"></p><small class="video-submit-note">点击生成会将所选图片及要求发送至智谱，费用按服务账户结算。</small></section></div></aside>
      <button type="button" id="reopenVideoSettings" class="paired-reopen-settings" aria-label="展开视频设置"><span>←</span><span>视频设置</span></button>`;
    detail.after(pair);
    const dialogs=document.createElement('div');dialogs.innerHTML=`<dialog id="videoConfigDialog" class="video-dialog"><form id="videoConfigForm"><header><h2>视频生成服务</h2><button type="button" data-close aria-label="关闭视频服务设置">×</button></header><p>智谱 CogVideoX-3 · 与图片服务独立配置</p><label for="videoApiKey">智谱 API 密钥</label><input id="videoApiKey" type="password" autocomplete="off" placeholder="填写已开通视频模型权限的 API 密钥" required minlength="8"><small>密钥仅在本机加密保存，不在浏览器中储存。</small><p id="videoConfigStatus" role="status"></p><button type="submit" class="video-dialog-primary">保存配置</button></form></dialog><dialog id="videoPickerDialog" class="video-dialog video-picker-dialog"><header><h2>选择商品图片</h2><button type="button" data-close aria-label="关闭图片选择">×</button></header><p>选一张清晰的产品照片作为视频首帧</p><div id="videoPickerGrid"></div><p id="videoPickerStatus" role="status"></p></dialog>`;document.body.append(dialogs);
    setup(pair);return true;
  }
  function setup(pair){
    const $=id=>document.getElementById(id);let source=null,motion='push',jobs=[],selectedId=null,activeId=null,timer=null,refreshing=false,submitting=false,loadingSource=false,config={configured:false},previewKey='';
    const active=j=>['queued','submitting','running'].includes(j.status);
    function status(message){$('videoStatus').textContent=message;}
    async function request(url,data){const response=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'请求失败');return result;}
    function controls(){const pending=jobs.find(active);activeId=pending?.id||null;$('videoGenerate').disabled=submitting||loadingSource||!!pending;$('videoGenerate').textContent=submitting?'正在提交…':pending?'视频生成中…':'生成视频';$('videoCancel').hidden=!pending;$('videoCancel').disabled=submitting;$('videoPlan').textContent='1 条 · '+$('videoDuration').value+' 秒';}
    async function service(){config=await request('/api/video/status');$('videoServiceStatus').textContent=config.configured?'智谱视频 · 已配置':'尚未配置视频服务';$('videoConfigure').textContent=config.configured?'更换密钥':'配置服务';}
    function safeLocalImage(url){try{const u=new URL(url,location.href);return u.origin===location.origin&&/^\/generated\/[a-f0-9-]{36}\/\d+(?:-repair-[12])?\.(png|jpg|webp)$/.test(u.pathname)?u.pathname:null;}catch{return null;}}
    async function readImage(file,name){if(loadingSource)return;loadingSource=true;controls();try{
      if(file.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 10 MB 以内的 PNG、JPG 或 WebP 图片');
      const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>50000000)throw Error('图片尺寸过大，请缩小后上传');const canvas=document.createElement('canvas'),scale=Math.min(1,1920/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);source={image:canvas.toDataURL('image/jpeg',.95),name:name||'商品图片'};}finally{bitmap.close();}
      $('videoSourceThumb').src=source.image;$('videoSourceName').textContent=source.name;$('videoSourceRow').hidden=false;$('videoUpload').classList.add('has-source');selectedId=null;previewKey='';renderPreview();status('素材已就绪，确认设置后即可生成视频');
    }catch(error){status(error.message);}finally{loadingSource=false;controls();}}
    async function fromUrl(url,name){const local=safeLocalImage(url);if(!local)throw Error('请选择网站中已生成的商品图片，或直接上传图片');const res=await fetch(local);if(!res.ok)throw Error('图片读取失败');await readImage(await res.blob(),name);}
    function renderPreview(){const j=jobs.find(j=>j.id===selectedId),key=j?j.id+':'+j.status:'source:'+(source?.image||'');if(previewKey===key)return;previewKey=key;const completed=j?.status==='completed',poster=j?.poster||source?.image;$('videoPlayer').pause();$('videoPlayer').hidden=!completed;$('videoSourcePreview').hidden=completed||!poster;$('videoEmpty').hidden=!!poster||completed;$('videoPreviewBadge').hidden=completed||!poster;$('videoPreviewStage').classList.toggle('has-media',!!poster||completed);
      if(completed){$('videoPlayer').src=j.url;$('videoPlayer').poster=j.poster;$('videoDownload').href=j.url;$('videoDownload').download='织景商品视频_'+j.id.slice(0,8)+'.mp4';}else{$('videoPlayer').removeAttribute('src');$('videoPlayer').load();if(poster)$('videoSourcePreview').src=poster;}
      $('videoDownload').hidden=!completed;$('videoPreviewCaption').textContent=j?(j.status==='completed'?'视频作品':'首帧预览')+' · '+j.duration+' 秒 · '+({source:'跟随原图','9:16':'9:16','16:9':'16:9','1:1':'1:1'}[j.ratio]||''):source?'已选素材 · '+source.name:'商品展示 · 连续镜头';
      let resume=$('videoResume');if(!resume){resume=document.createElement('button');resume.id='videoResume';resume.type='button';resume.textContent='继续获取原任务';resume.title='继续查询原有任务，不重新提交生成';$('videoDownload').before(resume);resume.onclick=async()=>{resume.disabled=true;try{await request('/api/video/jobs/'+selectedId+'/resume',{});await refresh();}catch(error){status(error.message);}finally{resume.disabled=false;}};}resume.hidden=!j?.canResume;
    }
    function render(){
      $('videoWorksCount').textContent='视频作品 · '+jobs.filter(j=>j.status==='completed').length;const list=$('videoJobList');list.replaceChildren();
      if(!jobs.length){const empty=document.createElement('p');empty.className='video-list-empty';empty.textContent='生成的视频和任务记录将在这里显示';list.append(empty);}
      for(const j of jobs){const button=document.createElement('button');button.type='button';button.className='video-job'+(selectedId===j.id?' is-selected':'');button.setAttribute('aria-pressed',String(selectedId===j.id));const image=document.createElement('img');image.src=j.poster;image.alt='视频首帧';image.loading='lazy';const text=document.createElement('span'),title=document.createElement('strong'),meta=document.createElement('small');title.textContent=({completed:'视频作品',queued:'排队中',submitting:'提交中',running:'生成中',failed:'生成失败',cancelled:'已停止'}[j.status]||'视频任务')+' · '+j.duration+' 秒';meta.textContent=new Date(j.created).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});text.append(title,meta);const mark=document.createElement('span');mark.className='video-job-mark';mark.textContent=j.status==='completed'?'▷':active(j)?'…':'—';button.append(image,text,mark);button.onclick=()=>{selectedId=j.id;renderPreview();render();if(!activeId)status(j.message);};list.append(button);}
      renderPreview();controls();const pending=jobs.find(active);$('videoProgress').hidden=!pending;if(pending){if(pending.progress==null)$('videoProgress').removeAttribute('value');else $('videoProgress').value=pending.progress;status(pending.message+(pending.progress!=null?' · '+pending.progress+'%':''));}
    }
    async function refresh(){if(refreshing)return;refreshing=true;clearTimeout(timer);try{const data=await request('/api/video/jobs');const previouslyActive=activeId;jobs=data.jobs||[];if(!selectedId&&!source)selectedId=(jobs.find(active)||jobs.find(j=>j.status==='completed')||jobs[0])?.id||null;render();if(previouslyActive&&!activeId){const finished=jobs.find(j=>j.id===previouslyActive);if(finished)status(finished.message);}}catch(error){status(error.message);}finally{refreshing=false;if(jobs.some(active))timer=setTimeout(refresh,3000);}}
    $('videoSourceFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(file)await readImage(file,file.name);};for(const id of ['videoUpload','videoEmptyUpload'])$(id).onclick=()=>$('videoSourceFile').click();
    $('videoUpload').ondragover=e=>{e.preventDefault();e.currentTarget.classList.add('is-dragover');};$('videoUpload').ondragleave=e=>e.currentTarget.classList.remove('is-dragover');$('videoUpload').ondrop=e=>{e.preventDefault();e.currentTarget.classList.remove('is-dragover');const file=e.dataTransfer.files[0];if(file)readImage(file,file.name);};
    $('videoClearSource').onclick=()=>{source=null;$('videoSourceRow').hidden=true;$('videoUpload').classList.remove('has-source');if(!selectedId){previewKey='';renderPreview();}status('已移除素材');};
    $('videoUseCurrent').onclick=async()=>{try{const current=typeof state!=='undefined'?state.results[state.selected]:null;if(!current||current.reference)throw Error('请先在图片设计中选择一张已生成的商品图片');await fromUrl(current.url,'当前图片'+(current.number?' #'+current.number:''));}catch(error){status(error.message);}};
    $('videoPickHistory').onclick=async()=>{$('videoPickerDialog').showModal();$('videoPickerStatus').textContent='正在读取作品…';$('videoPickerGrid').replaceChildren();try{const data=await request('/api/history');const items=(data.images||[]).filter(x=>!x.detailPage&&!x.deletedAt&&safeLocalImage(x.url));$('videoPickerStatus').textContent=items.length?'':'暂无可用图片，请先生成商品图片或上传素材';for(const item of items){const button=document.createElement('button');button.type='button';const img=document.createElement('img');img.src=item.url;img.alt='商品图片 #'+item.number;img.loading='lazy';const label=document.createElement('span');label.textContent='#'+item.number;button.append(img,label);button.onclick=async()=>{try{await fromUrl(item.url,'商品图片 #'+item.number);$('videoPickerDialog').close();}catch(error){$('videoPickerStatus').textContent=error.message;}};$('videoPickerGrid').append(button);}}catch(error){$('videoPickerStatus').textContent=error.message;}};
    pair.querySelectorAll('[data-motion]').forEach(button=>button.onclick=()=>{motion=button.dataset.motion;pair.querySelectorAll('[data-motion]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});$('videoDuration').onchange=controls;
    $('videoConfigure').onclick=()=>{$('videoConfigStatus').textContent='';$('videoConfigDialog').showModal();};dialogsClose();
    function dialogsClose(){for(const dialog of [$('videoConfigDialog'),$('videoPickerDialog')])dialog.querySelector('[data-close]').onclick=()=>dialog.close();$('videoConfigDialog').addEventListener('close',()=>$('videoApiKey').value='');}
    $('videoConfigForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{config=await request('/api/service/video',{apiKey:$('videoApiKey').value});$('videoApiKey').value='';await service();$('videoConfigDialog').close();status('视频服务配置已保存，尚未提交生成任务');}catch(error){$('videoConfigStatus').textContent=error.message;}finally{button.disabled=false;}};
    $('videoGenerate').onclick=async()=>{if(submitting||activeId)return;if(!source){status('请先上传或选择商品图片');return;}if(!config.configured){$('videoConfigure').click();return;}submitting=true;controls();try{const j=await request('/api/video/jobs',{image:source.image,motion,prompt:$('videoPrompt').value,duration:Number($('videoDuration').value),quality:$('videoQuality').value,ratio:$('videoRatio').value,audio:$('videoAudio').checked});selectedId=j.id;activeId=j.id;jobs.unshift(j);render();status(j.message);await refresh();}catch(error){status(error.message);}finally{submitting=false;controls();}};
    $('videoCancel').onclick=async()=>{if(!activeId)return;try{await request('/api/video/jobs/'+activeId+'/cancel',{});status('已请求停止跟踪，供应商可能仍在生成并计费');await refresh();}catch(error){status(error.message);}};$('videoRefresh').onclick=refresh;
    const main=$('videoDesignModule'),rail=$('videoSettingsPanel');main.addEventListener('toggle',()=>{pair.classList.toggle('video-workspace-closed',!main.open);main.querySelector('.workspace-section-toggle').textContent=main.open?'收起 ↑':'展开 ↓';main.querySelector('summary').setAttribute('aria-expanded',String(main.open));});
    function collapse(value){pair.classList.toggle('detail-settings-collapsed',value);rail.inert=value;$('collapseVideoSettings').setAttribute('aria-expanded',String(!value));(value?$('reopenVideoSettings'):$('collapseVideoSettings')).focus();}$('collapseVideoSettings').onclick=()=>collapse(true);$('reopenVideoSettings').onclick=()=>collapse(false);
    service().catch(error=>{$('videoServiceStatus').textContent='视频服务读取失败';status(error.message);});refresh();controls();
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});window.addEventListener('pagehide',()=>clearTimeout(timer));
  }
  if(!mount()){const observer=new MutationObserver(()=>{if(mount())observer.disconnect();});observer.observe(document.getElementById('workspace'),{childList:true,subtree:true});}
})();
